#include <stdint.h>

// AI: below section was generated by an AI
// Shared conversion/range policy for lab and production. Vishay application note 84323, Rev. 06-Mar-2025:
// https://www.vishay.com/docs/84323/designingveml7700.pdf
// The coefficients are NOMINAL; use physical calibration for product thresholds.
namespace lumacore_veml7700 {

struct Profile {
  uint8_t gainBits;
  uint8_t integrationBits;
  uint16_t integrationMs;
  float luxPerCount;
  const char* gainLabel;
};

// From least to most sensitive. Begin at index 1, per Vishay low-gain startup
// recommendation, and switch to x2/800 ms only at low irradiance.
static constexpr Profile profiles[] = {
  { 2, 12,  25, 2.1504f, "1/8" },
  { 2,  0, 100, 0.5376f, "1/8" },
  { 2,  3, 800, 0.0672f, "1/8" },
  { 3,  3, 800, 0.0336f, "1/4" },
  { 0,  3, 800, 0.0084f, "1" },
  { 1,  3, 800, 0.0042f, "2" }
};
static constexpr uint8_t profileCount = sizeof(profiles) / sizeof(profiles[0]);
static constexpr uint8_t startProfile = 1;

// No interrupt/power-saving/shutdown; bits 12:11 = gain, 9:6 = integration.
inline uint16_t configWord(uint8_t index) {
  const Profile& p = profiles[index];
  return (static_cast<uint16_t>(p.gainBits) << 11) |
         (static_cast<uint16_t>(p.integrationBits) << 6);
}

// Keep the ADC away from saturation while resolving <64 counts by raising
// sensitivity. Wide thresholds avoid ping-pong under steady illumination.
inline uint8_t nextProfile(uint8_t index, uint16_t alsRaw) {
  if (alsRaw >= 12000 && index > 0) return index - 1;
  if (alsRaw < 64 && index + 1 < profileCount) return index + 1;
  return index;
}

inline float nominalLux(uint8_t index, uint16_t alsRaw) {
  return static_cast<float>(alsRaw) * profiles[index].luxPerCount;
}

inline uint32_t settlingMs(uint8_t index) {
  // Conservative double-integration guard includes device oscillator settle.
  return static_cast<uint32_t>(profiles[index].integrationMs) * 2U + 10U;
}
} // namespace lumacore_veml7700
